const base='/api/lounge/v2/stage-bridge';
export const consoleStyle=`:root{color-scheme:dark}body{background:var(--void);color:var(--text-high);font:16px system-ui;margin:32px;max-width:1100px}a{color:var(--cyan)}button,select{font:inherit;padding:12px;margin:8px;border:1px solid var(--text-faint);border-radius:6px}button:focus-visible,select:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}article{border:1px solid var(--text-faint);margin:24px 0;padding:24px;border-radius:16px}img{max-width:100%;max-height:450px;display:block;background:var(--panel)}p{line-height:1.5}button:disabled{opacity:.5}`;
export function consoleHtml(csrf){if(typeof csrf!=='string'||!/^[A-Za-z0-9_-]{16,128}$/.test(csrf))throw Error('Invalid CSRF token');return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf" content="${csrf}"><title>CUHZ Lounge — Artwork review</title><link rel="stylesheet" href="/api/lounge/v2/stage/tokens.css"><link rel="stylesheet" href="${base}/console.css"></head><body><main><h1>Artwork review</h1><p>Only artwork members deliberately submitted appears here. Approval makes an item eligible for the stage; showing it is a separate action.</p><p><a href="/api/lounge/v2/stage/ops">Stage controls</a></p><button id="refresh">Refresh queue</button><p id="status" role="status" aria-live="polite">Loading review queue…</p><section id="queue" aria-label="Submitted artwork"></section></main><script src="${base}/console.js" defer></script></body></html>`;}
export const consoleScript=`'use strict';
const base=${JSON.stringify(base)},csrf=document.querySelector('meta[name=csrf]').content,status=document.querySelector('#status'),queue=document.querySelector('#queue');
const attempts=new Map();let busy=false;
const node=(name,text)=>{const n=document.createElement(name);if(text)n.textContent=text;return n;};
async function send(attempt,card){if(busy)return;busy=true;queue.querySelectorAll('button,select').forEach(n=>n.disabled=true);status.textContent='Recording decision…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const r=await fetch(base+'/review/decide',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Lounge-CSRF':csrf},body:JSON.stringify(attempt),signal:controller.signal});const result=await r.json();if(r.ok&&result.ok){attempts.delete(attempt.reviewId);status.textContent='Decision recorded. Refresh the queue to continue.';card.remove();}else if(result.error==='BRIDGE_OUTCOME_UNKNOWN'||r.status>=500){throw Error('unknown');}else{attempts.delete(attempt.reviewId);status.textContent='Decision refused: '+(result.code||result.error||'UNAVAILABLE');queue.querySelectorAll('button,select').forEach(n=>n.disabled=n.dataset?.decision==='approved'&&n.dataset?.loaded!=='true');}}catch{status.textContent='Outcome unknown. Use Recover decision to retry the same receipt. Do not create another decision.';let recovery=card.querySelector('.recover');if(!recovery){recovery=node('button','Recover decision');recovery.className='recover';recovery.onclick=()=>send(attempt,card);card.append(recovery);}recovery.disabled=false;}finally{clearTimeout(timer);busy=false;}}
async function load(){if(busy||attempts.size){status.textContent='Recover the pending decision before refreshing.';return;}busy=true;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const r=await fetch(base+'/reviews',{credentials:'same-origin',signal:controller.signal});if(!r.ok)throw Error('unavailable');const data=await r.json();queue.replaceChildren();for(const item of data.reviews){const card=node('article'),image=node('img');let imageReady=false;image.onload=async()=>{try{await image.decode();imageReady=true;const approve=card.querySelector('[data-decision=approved]');if(approve){approve.dataset.loaded='true';if(!busy&&!attempts.size)approve.disabled=false;}}catch{status.textContent='Artwork could not be decoded. Approval remains disabled.';}};image.onerror=()=>{status.textContent='Artwork unavailable. Approval remains disabled.';};image.src=item.imageUrl;image.alt=item.title;card.append(node('h2',item.title),node('p',item.displayName+' · '+item.label),image);const select=node('select');select.setAttribute('aria-label','Decision reason');for(const reason of ['content_reviewed','content_policy','rights_unclear','quality_issue']){const option=node('option',reason.replaceAll('_',' '));option.value=reason;select.append(option);}card.append(select);for(const decision of ['approved','rejected']){const button=node('button',decision==='approved'?'Approve':'Reject');button.dataset.decision=decision;button.dataset.loaded=imageReady?'true':'false';button.disabled=decision==='approved'&&!imageReady;button.onclick=()=>{if(busy||attempts.size||(decision==='approved'&&!imageReady))return;const attempt={requestId:crypto.randomUUID(),reviewId:item.id,decision,reason:select.value};attempts.set(item.id,attempt);send(attempt,card);};card.append(button);}queue.append(card);}status.textContent=data.reviews.length?'Review each image and choose a reason.':'No pending submissions.';}catch{status.textContent='Review queue unavailable. Refresh deliberately to try again.';}finally{clearTimeout(timer);busy=false;}}
document.querySelector('#refresh').onclick=load;load();`;
